head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05014";
scwin.LD_MKT_TP_CD = '1';
scwin.NEWSEL = 4;
scwin.BZ_NEWPRE = 0;
scwin.BZ_ADDPRE = 2;
scwin.BZ_ADDLST = 3;
scwin.CD_NEWPRE = '002';
scwin.form = null;
scwin.upd_elwAttachDocBinfile = null;

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — uploadCode

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_elwAttachDocBinfile = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_elwAttachDocBinfile') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_elwAttachDocBinfile"]');
        scwin.init_fillGen();
        scwin.init_conds();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05014.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_Register", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === 4); } }, { id: "btn_Edit", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  ===  2); } }, { id: "btn_ElwSub", fn: function(){ return ((dma_readDataVO.get("listProcsStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listProcsStatCd"); })()) === '00' && (dma_readDataVO.get("billLstSaveStatCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.billLstSaveStatCd"); })())  >=  4); } }, { id: "ipt_editYn", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (0+1)); } }, { id: "ipt_editYn_r1", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r1", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (1+1)); } }, { id: "ipt_editYn_r2", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r2", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (2+1)); } }, { id: "ipt_editYn_r3", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r3", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (3+1)); } }, { id: "ipt_editYn_r4", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r4", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (4+1)); } }, { id: "ipt_editYn_r5", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r5", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (5+1)); } }, { id: "ipt_editYn_r6", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r6", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (6+1)); } }, { id: "ipt_editYn_r7", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r7", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (7+1)); } }, { id: "ipt_editYn_r8", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r8", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (8+1)); } }, { id: "ipt_editYn_r9", fn: function(){ return ((dma_readDataVO.get("transKind") ?? (() => { throw new Error("unresolved:" + "readDataVO.transKind"); })())  === '2'); } }, { id: "btn_FileDown_r9", fn: function(){ return ((dlt_readDataVOArrayAttach.getCellData(0, "elwAttachSeq") ?? (() => { throw new Error("unresolved:" + "entity.elwAttachSeq"); })()) === (9+1)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_68", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r1", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r1", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r2", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r2", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r3", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r3", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r4", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r4", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r5", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r5", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r6", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r6", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r7", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r7", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r8", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r8", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] },
        { genId: "c_foreach_68_r9", entity: "dlt_readDataVOArrayAttach", countIds: [], cells: [{ childId: "btn_FileDown_r9", fn: function (v, i) { return String(v("elwAttachSaveDocNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.ElwForm || { elements: [] });
        $c.util.getComponent("dma_FileDownReq").set("bzCd", scwin.BZ_NEWPRE);
        $c.util.getComponent("dma_FileDownReq").set("listBzTpCd", scwin.CD_NEWPRE);
        $c.util.getComponent("dma_FileDownReq").set("spotIsuTrdMktTpCd", scwin.LD_MKT_TP_CD);
        /* 수동 전환 필요: transTbl[0].value 대입 — 그룹 항목 값은 옵션표가 정한다 */
        await scwin.checkSave();
        await (async () => { const m = $c.util.getComponent("dma_readDataVO"); const v = (m && m.get) ? m.get("resultMsg") : ""; if (v) { await $c.win.alert(String(v)); } })();
        if ($c.util.getComponent('ipt_transKind').getValue() === '2') {
            await scwin.setFile2ReadOnly();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05014.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: entry_edge). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Register_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05014.btn_Register_onclick' }); }
};

