 * @description 「N」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_editYn_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.editAttach(selfVar,0)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05014.ipt_editYn_onclick' }); }
};

/**
 * @method
 * @name btn_FileDown_onclick
