/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function (action) {
    try { return await $c.data.downFile(action ?? "/common/irDataFileDown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const uploadCode = (String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCode") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCode") ?? ""))));
    if (uploadCode === '0') {
        await $c.win.alert('저장되었습니다.');
    } else {
        if (uploadCode === '1') {
            await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
        } else {
            if (uploadCode === '2') {
                await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
            }
        }
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} elwAttachSeq elwAttachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (bzProcsNo, elwAttachSeq) {
    $c.util.getComponent('dma_FileDownReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent('dma_FileDownReq').set('elwAttachSeq', elwAttachSeq);
    $c.util.getComponent('dma_FileDownReq').set('method', 'searchElwFileDown');
    await scwin.tx_fn_FileDown('/common/irDataFileDown.do');
};

/**
 * @method
 * @name newSearch
 * @description new Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newSearch = async function () {
    $c.util.getComponent("dma_FileDownReq").set("transKind", scwin.NEWSEL);
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_FileDownReq').set('method', 'searchElw');
    await scwin.tx_fn_NewSearch();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await scwin.isPossibleSave()) {
        return;
    }
    if (!scwin.isMustAttachAdded()) {
        return;
    }
    if (!await $c.fil.confirmJob('I')) {
        return;
    }
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_FileDownReq').set('method', 'registerElw');
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name isMustAttachAdded
 * @description is Must Attach Added 처리
 * @returns {void}
 * @hidden N
 */
scwin.isMustAttachAdded = function () {
    return true;
};

/**
 * @method
 * @name edit
 * @description edit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edit = async function () {
    if (isNotAdmin()) {
        if (scwin.isExistEditItem()) {
            if (scwin.isMustAttachAdded()) {
                scwin.setEditYn();
                scwin.form.action = '/list/elw.do';
                $c.util.getComponent('dma_FileDownReq').set('method', 'updateElwAttach');
                await scwin.tx_fn_Edit();
            }
        } else {
            await $c.win.alert("수정한 내용이 없습니다.");
        }
    }
};

/**
 * @method
 * @name isExistEditItem
 * @description is Exist Edit Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.isExistEditItem = function () {
    const chkObj = document.getElementsByName('editYn');
    let isExist = false;
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i].checked === true) {
            isExist = true;
            break;
        }
    }
    return isExist;
};

/**
 * @method
 * @name setEditYn
 * @description set Edit Yn 처리
 * @returns {void}
 * @hidden N
 */
scwin.setEditYn = function () {
    const chkObj = document.getElementsByName('editYn');
    const tORf = true;
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i].checked === tORf) {
            chkObj[i].value = 'Y';
        } else {
            chkObj[i].value = 'N';
        }
        chkObj[i].checked = true;
    }
};

/**
 * @method
 * @name editAttach
 * @description edit Attach 처리
 * @param {*} obj1 obj1
 * @param {*} ver1 ver1
 * @returns {void}
 * @hidden N
 */
scwin.editAttach = function (obj1, ver1) {
    const fileObj = scwin.form['elwAttachDocBinfile['+ver1+']'];
    if (obj1.checked === true) {
        fileObj.readOnly = false;
    } else {
        fileObj.readOnly = true;
    }
};

/**
 * @method
 * @name setFile2ReadOnly
 * @description set File2 Read Only 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setFile2ReadOnly = async function () {
    let fileObj;
    for (let i = 0; i < 10; i++) {
        fileObj = (document.ElwForm || { elements: [] })['elwAttachDocBinfile['+i+']'];
        try {
            fileObj.readOnly = true;
        } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil05014' });
            await $c.win.alert(i);
        }
    }
};

